// Light on the water. iChannel0 and iChannel1 both read Buffer A: the
// left half pixel by pixel, the right half smoothed.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
	vec2 uv = fragCoord / iResolution.xy;
	vec2 texel = 1.0 / iChannelResolution[0].xy;
	float here, right, up;
	if (uv.x < 0.5) {
		here = texture(iChannel0, uv).x;
		right = texture(iChannel0, uv + vec2(texel.x, 0.0)).x;
		up = texture(iChannel0, uv + vec2(0.0, texel.y)).x;
	} else {
		here = texture(iChannel1, uv).x;
		right = texture(iChannel1, uv + vec2(texel.x, 0.0)).x;
		up = texture(iChannel1, uv + vec2(0.0, texel.y)).x;
	}
	vec3 normal = normalize(vec3(here - right, here - up, 0.05));
	float light = dot(normal, normalize(vec3(0.4, 0.5, 0.8)));
	fragColor = vec4(vec3(0.1, 0.3, 0.5) + 0.6 * light, 1.0);
}

// The height of a water surface. It reads itself (iChannel0) and the
// speed in Buffer B (iChannel1), which is drawn after this buffer, so
// both are of the frame before.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
	ivec2 p = ivec2(fragCoord);
	float height = texelFetch(iChannel0, p, 0).x;
	height += texelFetch(iChannel1, p, 0).x;
	// A drop every half second, or wherever the finger is.
	vec2 c = iMouse.z > 0.0
		? iMouse.xy
		: iResolution.xy * (0.5 + 0.3 * vec2(cos(iTime), sin(0.7 * iTime)));
	if (iFrame % 30 == 0 || iMouse.z > 0.0) {
		vec2 d = fragCoord - c;
		height += 0.5 * exp(-dot(d, d) / 40.0);
	}
	fragColor = vec4(height, 0.0, 0.0, 1.0);
}

// The speed of the surface. It reads the height in Buffer A
// (iChannel0), which was drawn before this buffer in the same frame,
// and itself (iChannel1) of the frame before. The speed is negative
// where the surface falls: the buffer keeps floats.
float heightAt(ivec2 p) {
	return texelFetch(iChannel0,
		clamp(p, ivec2(0), ivec2(iResolution.xy) - 1), 0).x;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
	ivec2 p = ivec2(fragCoord);
	float around = heightAt(p + ivec2(1, 0)) + heightAt(p - ivec2(1, 0)) +
		heightAt(p + ivec2(0, 1)) + heightAt(p - ivec2(0, 1));
	float speed = texelFetch(iChannel1, p, 0).x;
	speed = 0.995 * (speed + 0.2 * (around - 4.0 * heightAt(p)));
	fragColor = vec4(speed, 0.0, 0.0, 1.0);
}
